contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, uint256 amount) public {
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool ok = true;
        // stake on behalf of this contract (msg.sender = this)
        // note: c.stake calls safeTransferFrom(msg.sender, c, amount) using the staking token
        // we cannot change c.stakingToken, so instead simulate the general rule via withdraw check:
        // a withdrawal attempt larger than the staked balance must always revert.
        bool reverted;
        try c.withdraw(amount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: any withdraw attempt succeeds only if amount <= caller's staked balance;
        // when it succeeds, balance and totalSupply each drop by exactly amount.
        if (!reverted) {
            assert(amount <= balBefore);
            assert(c.balanceOf(address(this)) == balBefore - amount);
            assert(c.totalSupply() == supplyBefore - amount);
        } else {
            assert(c.balanceOf(address(this)) == balBefore);
            assert(c.totalSupply() == supplyBefore);
        }
        assert(true);
    }
    receive() external payable {}
}

