contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public {
        // Owner (this contract) adds a fresh reward token; must succeed.
        c.addReward(token);

        // The token must be registered exactly once in rewardTokens.
        uint256 count;
        uint256 len = 0;
        bool more = true;
        while (more) {
            bool ok;
            address t;
            (ok, t) = probeList(len);
            if (!ok) { more = false; }
            else {
                if (t == token) count++;
                len++;
            }
        }
        require(count == 1);

        // Re-adding the same token must revert.
        bool reverted;
        (reverted, ) = this.tryReAdd(token);

        uint40 finish = c.rewardPeriodFinish(token);
        (, uint216 rate, uint40 lastUpdate, ) = c.rewardData(token);

        assert(
            reverted &&
            finish == uint40(block.timestamp) &&
            lastUpdate == uint40(block.timestamp) &&
            rate == 0
        );
    }

    function probeList(uint256 i) internal view returns (bool ok, address t) {
        bytes4 sel = 0x78d7be46; // rewardTokens(uint256)
        (bool success, bytes memory ret) = address(c).staticcall(abi.encodeWithSelector(sel, i));
        if (!success || ret.length < 32) return (false, address(0));
        return (true, abi.decode(ret, (address)));
    }
}

